const items = $input.all();

return items.map(item => {
  const body = item.json.body || item.json;

  // Extracción de variables con nombres alternativos de seguridad
  const destinatario = body.correo || body.email || body.userEmail;
  const nombre = body.nombre || body.userName || 'Deportista';
  const ticketId = body.ticketId || body.reservaId || 'TKT-PENDING';
  const cancha = body.cancha || body.courtName || 'Cancha Principal';
  const sede = body.sede || body.venueName || 'AKROS Club';
  const fecha = body.fecha || body.date || new Date().toISOString().split('T')[0];
  const franjaHoraria = body.franjaHoraria || body.timeSlot || 'Por definir';

  // Generación de la imagen del QR y enlace a billetera del portal
  const qrPayload = body.qrPayload || body.qrCode || ticketId;
  const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(qrPayload)}`;
  const appBaseUrl = body.appUrl || 'https://akros.lat';
  const walletUrl = `${appBaseUrl}/portal/wallet?ticket=${encodeURIComponent(ticketId)}`;

  // Plantilla HTML con diseño oficial AKROS Club
  const htmlTemplate = `
  <!DOCTYPE html>
  <html lang="es">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
      body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background-color: #0d1210; margin: 0; padding: 24px; color: #ffffff; }
      .card { max-width: 500px; margin: 0 auto; background: #111815; border: 1px solid #1a2420; border-radius: 16px; padding: 32px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); }
      .badge { display: inline-block; background: rgba(201, 239, 117, 0.15); color: #c9ef75; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; padding: 6px 12px; border-radius: 9999px; margin-bottom: 16px; }
      h1 { font-size: 22px; margin: 0 0 8px 0; color: #ffffff; font-weight: 700; }
      p.lead { color: #94a3b8; font-size: 14px; margin-top: 0; margin-bottom: 24px; }
      .qr-container { background: #ffffff; border-radius: 12px; padding: 18px; text-align: center; display: inline-block; margin: 10px auto 24px auto; }
      .qr-container img { display: block; margin: 0 auto; width: 220px; height: 220px; }
      .details-box { background: #16201b; border: 1px solid #23322b; border-radius: 10px; padding: 16px; margin-bottom: 24px; text-align: left; }
      .detail-row { display: flex; justify-content: space-between; margin-bottom: 8px; font-size: 13px; }
      .detail-row:last-child { margin-bottom: 0; }
      .detail-label { color: #64748b; }
      .detail-value { color: #f1f5f9; font-weight: 600; font-family: ui-monospace, monospace; }
      .btn-wallet { display: block; text-align: center; background: #c9ef75; color: #111815; font-weight: 700; font-size: 14px; text-decoration: none; padding: 14px 20px; border-radius: 8px; margin-bottom: 20px; }
      .footer { font-size: 12px; color: #475569; text-align: center; line-height: 1.5; border-top: 1px solid #1a2420; padding-top: 20px; }
    </style>
  </head>
  <body>
    <div class="card">
      <div style="text-align: center;">
        <div class="badge">Acceso Confirmado</div>
        <h1>Tu Pase Deportivo</h1>
        <p class="lead">Hola ${nombre}, presenta este QR directamente en el lector de portería.</p>
        <div class="qr-container">
          <img src="${qrImageUrl}" alt="Boleto QR" />
        </div>
      </div>
      <div class="details-box">
        <div class="detail-row"><span class="detail-label">Instalación:</span><span class="detail-value">${cancha}</span></div>
        <div class="detail-row"><span class="detail-label">Sede:</span><span class="detail-value">${sede}</span></div>
        <div class="detail-row"><span class="detail-label">Fecha:</span><span class="detail-value">${fecha}</span></div>
        <div class="detail-row"><span class="detail-label">Franja:</span><span class="detail-value">${franjaHoraria}</span></div>
        <div class="detail-row"><span class="detail-label">ID Boleto:</span><span class="detail-value">${ticketId}</span></div>
      </div>
      <a href="${walletUrl}" target="_blank" class="btn-wallet">Abrir en Billetera Digital del Portal</a>
      <div class="footer">
        Presenta este código al ingresar. Llegar con 10 min de anticipación.<br>
        AKROS Club &copy; 2026. Todos los derechos reservados.
      </div>
    </div>
  </body>
  </html>
  `;

  return {
    json: {
      destinatario,
      asunto: `Tu boleto de acceso para ${cancha} - AKROS Club`,
      html: htmlTemplate,
      ticketId,
      dispatchedAt: new Date().toISOString()
    }
  };
});
